import 'package:family_veda/models/member.dart';
import 'package:family_veda/screens/appointments/book_appointment_screen.dart';
import 'package:flutter_test/flutter_test.dart';

void main() {
  final self = const Member(id: 'self-1', displayName: 'Self', relationshipLabel: 'Head');
  final adultSpouse = const Member(
    id: 'adult-1',
    displayName: 'Spouse',
    relationshipLabel: 'Adult',
    dateOfBirth: '1990-01-01',
  );
  final minorChild = Member(
    id: 'minor-1',
    displayName: 'Child',
    relationshipLabel: 'Minor',
    dateOfBirth: DateTime.now().subtract(const Duration(days: 365 * 10)).toIso8601String(),
  );
  final allMembers = [self, adultSpouse, minorChild];

  test('Adult member sees only self as a bookable option', () {
    final options = bookableMembers(
      allMembers: allMembers,
      activeMemberId: self.id,
      isHead: false,
    );
    expect(options.map((m) => m.id), [self.id]);
  });

  test('Head sees self plus minors, but not other adults', () {
    final options = bookableMembers(
      allMembers: allMembers,
      activeMemberId: self.id,
      isHead: true,
    );
    final ids = options.map((m) => m.id).toSet();
    expect(ids, {self.id, minorChild.id});
    expect(ids.contains(adultSpouse.id), isFalse);
  });

  test('Head with no active member still gets minors', () {
    final options = bookableMembers(
      allMembers: allMembers,
      activeMemberId: null,
      isHead: true,
    );
    expect(options.map((m) => m.id), contains(minorChild.id));
  });
}
